/*Preliminaries		*/
/*Set up libraries	*/
libname bnk "[redacted-path-344c417e228f]";
libname edo "[redacted-path-4ad59154fe43]";
libname mod "[redacted-path-afdbc51d344a]";
libname fail "[redacted-path-bbf95d26ce07]";
%INCLUDE "[redacted-path-76bce5fd35ae]";

/* Download and calculate required variables from call report data */
/* Dates refer to data availability in dataset master_commercial */

proc sql;
create table RelVar as select
	RSSD9001 as RSSDID,
	RSSD9999 as DATE,

/* Winsorize variables of interest */

*** variables to be winsorized;
* winsorize first group: 1983.1 ~ 1997.4;
%let win_main= CAPITAL_RATIO npa roa ROA_QTR DEPOSIT_SC LOAN_SC size LIQ_CASH SIZE_LAG1 NPA_LAG1 NPA_LAG2 NPA_LAG3 NPA_LAG4 NET_CHRGOFF_LAG1
NET_CHRGOFF_LAG2 NET_CHRGOFF_LAG3 NET_CHRGOFF_LAG4 CAPITAL_RATIO_LAG1 CAPITAL_RATIO_LAG2 CAPITAL_RATIO_LAG3 CAPITAL_RATIO_LAG4 ROA_LAG1 
ROA_LAG2 ROA_LAG3 ROA_LAG4 ROA_QTR_LAG1 LIQ_CASH_LAG1 LIQ_CASH_LAG2 LIQ_CASH_LAG3 LIQ_CASH_LAG4 LOG_TOT_DEP CRE_LOAN_SC_TL CRE_LOAN_SC_TL_LAG1 
RRE_LOAN_SC_TL RRE_LOAN_SC_TL_LAG1 NON_RRE_LOAN_SC_TL NON_RRE_LOAN_SC_TL_LAG1 TIME_DEP TIME_DEP_SC TIME_DEP_UNINSURED TIME_DEP_UNINSURED_SC
BROKER_DEP BROKER_DEP_SC DEMAND_DEP DEMAND_DEP_SC TRANS_DEP TRANS_DEP_SC TIME_DEP_GE100K TIME_DEP_GE100K_SC TIME_DEP_LE100K TIME_DEP_LE100K_SC LOG_BROKER_DEP LOG_TIME_DEP_GE100K LOG_TIME_DEP_LE100K
RISKY_LOANS CRE ADC
;

%let win_main_suffix=%sysfunc(prxchange(s/(\w+)/$1W/,-1,&win_main)); 
%let WIN_MAIN_RENAME=%sysfunc(prxchange(s/(\w+)/$1=$1W/,-1,&win_main));
%put &WIN_MAIN_RENAME;

data var7_win_main(rename= (&WIN_MAIN_RENAME));
  set var7(keep= RSSDID YEAR_QTR &win_main);
  if year_qtr >= 1983.1 & year_qtr <= 1997.4;
run;

%winsor(dsetin= var7_win_main, dsetout= var7_win_main, byvar=YEAR_QTR, vars=&win_main_suffix, type=winsor, pctl=1 99);

proc sql;
create table var7_2 as select
	*
	from var7 as a 
	left join var7_win_main as b
	on a.RSSDID = b.RSSDID and a.YEAR_QTR = b.YEAR_QTR;
quit;

* winsorize second group: 1991.1 ~ 1997.4;
%let win_sub= INSURED_DEPOSIT UNINSURED_DEPOSIT LOG_INSURED LOG_UNINSURED;

%let win_sub_suffix=%sysfunc(prxchange(s/(\w+)/$1W/,-1,&win_sub)); 
%let WIN_sub_RENAME=%sysfunc(prxchange(s/(\w+)/$1=$1W/,-1,&win_sub));
%put &WIN_sub_RENAME;

data var7_win_sub(rename= (&win_sub_rename));
  set var7(keep= RSSDID YEAR_QTR &win_sub);
  if year_qtr >= 1991.1 & year_qtr <= 1997.4;
run;

%winsor(dsetin= var7_win_sub, dsetout= var7_win_sub, byvar=YEAR_QTR, vars=&win_sub_suffix, type=winsor, pctl=1 99);

proc sql;
create table var7_3 as select
	* 
	from var7_2 as a
	left join var7_win_sub as b
	on a.RSSDID = b.RSSDID and a.YEAR_QTR = b.YEAR_QTR;
quit;


proc means data = var7_3; 
	class YEAR_QTR; 
	var SIZE NPA NET_CHRGOFF CAPITAL_RATIO ROA ROA_QTR ROE NIM LIQ_CASH ch_NPA ch_CAPITAL_RATIO ch_LIQ_CASH INSURED_DEPOSIT UNINSURED_DEPOSIT; 
run; 


/* save */
data mod.bnk_vars; 
set var7_3; 
run; 

/************************************************************/
/* Include enforcement action data sourced from SNL financial, 
collected from termination documents and the National Archives
/************************************************************/

data edo1;
set edo.Edo_modified;
	keep RSSDID YEAR_QTR EVENT;
run;

data edo1a;
set edo1;
	if (1983.1 <= YEAR_QTR_EDO <= 2007.4); 
run;	

data var1;
set mod.bnk_vars;
	keep RSSDID YEAR_QTR TOT_ASSETS_LAG1 SIZE_LAG1 CAPITAL_RATIO_LAG1 NPA_LAG1 ROA_LAG1 ROA_QTR_LAG1 LIQ_CASH_LAG1 ch_CAPITAL_RATIO_LAG1 ch_LIQ_CASH_LAG1 CH_LOAN_LAG1 CRE_LOAN_SC_TL_LAG1 RRE_LOAN_SC_TL_LAG1 NON_RRE_LOAN_SC_TL_LAG1;
run;

proc sort data = var1;
	by RSSDID;
run;

proc sort data = edo1a;
	by RSSDID;
run;

data dat1;
merge var1(IN=in1) edo1a(IN=in2);
	by RSSDID;
	if in1 = 1 then output dat1;
run;

/* Format dates */

data dat1a;
set dat1;
	YEAR = (substr(compress(YEAR_QTR),1,4))*1;
	QTR = (substr(compress(YEAR_QTR),6,1))*1;

	MONTH = QTR*3;

	if MONTH = 3 then DAY = 31;
	else if MONTH = 6 then DAY = 30;
	else if MONTH = 9 then DAY = 30;
	else DAY = 31;

	DATE1 = mdy(MONTH,DAY,YEAR);
	format DATE1 mmddyy10.;
run;

proc sort data = dat1a nodupkey;
	by RSSDID YEAR_QTR;
run;

proc expand data=dat1a out=dat2 method=none;
	by RSSDID;
	id YEAR_QTR;
	convert DATE1 = DATE0 / transformout=(lag 1);
run; 

/* Create disclosure and EDO variable */ 

data dat3;
set dat2(rename=(event=edo_treat));
	if YEAR_QTR_EDO = YEAR_QTR then EDO = 1; /*12 quarters around the disclosure are computed based on this indicator*/
	else EDO = 0;

	if YEAR_QTR <= 1989.3 then DISC = 0;
	else DISC = 1;

	YEAR = (substr(compress(YEAR_QTR),1,4))*1;
	if edo_treat = . then edo_treat = 0;

	drop year_qtr_edo; 
run;

/* Include regulator id and distance from regulator variables */ 

data reg1;
set mod.all_bnk_dist_sas; 
	keep RSSDID DATE REGULATOR DIST_REG ;
run; 

data reg2;
set bnk.Master_commercial;
	keep RSSD9001 RSSD9999 RSSD9200 RSSD9331 RSSD9048;
run;

data reg2a;
set reg2;
	rename RSSD9331 = ENTITY_TYPE_CODE;
	rename RSSD9048 = CHARTER_TYPE;
run; 

data reg2b;
set reg2a;
	if CHARTER_TYPE = 200;
run;

proc sql;
create table reg3 as select
a.*,
b.RSSD9200
from reg1 as a, reg2b as b
where a.rssdid = b.rssd9001 and
	  a.date = b.RSSD9999;
quit;

data reg4;
set reg3;
	YEAR = (substr(compress(DATE),1,4))*1; 
	QTR = ((substr(compress(DATE),5,2))*1)/3;
	YEAR_QTR = (cat(YEAR,".",QTR))*1;
	log_dist = log(dist_reg); 
run; 

data dat10;
merge dat3(IN=in1) reg4(IN=in2);
	by RSSDID YEAR_QTR;
	if in1 = 1 then output dat10;
run;

/************************************************************/
/* Include news coverage of EDOs from handcollected dataset
/************************************************************/
proc sql;
	create table dat11 as select * from dat10 as a 
	left join mod.edo_media_coverage as b
	on a.RSSDID=b.RSSDID; 
quit;

/* save complete dataset */

data mod.surv_data_complete; 
set dat11; 
run; 

/* data for main analyses */

data mod.surv_data_8397; 
set mod.surv_data_complete; 
	if (1983.1 <= year_qtr <= 1997.4); 
	keep rssdid year_qtr year date0 date1 edo_treat edo_mat edo disc log_dist TOT_ASSETS_LAG1 SIZE_LAG1 CAPITAL_RATIO_LAG1 NPA_LAG1 
	ROA_LAG1 ROA_QTR_LAG1 LIQ_CASH_LAG1 ch_CAPITAL_RATIO_LAG1 ch_LIQ_CASH_LAG1 CH_LOAN_LAG1 capital_ratio_disc npa_disc roa_disc ROA_QTR_DISC liq_cash_disc CRE_LOAN_SC_TL_LAG1 RRE_LOAN_SC_TL_LAG1 NON_RRE_LOAN_SC_TL_LAG1;
run; 

proc export data=mod.surv_data_8397 replace
	outfile="[redacted-path-ac887a2747e5]"
	dbms = csv;
delimiter=',';
run;

/* data for robustness analyses */

data mod.surv_data_8307; 
set mod.surv_data_complete; 
	if (1983.1 <= year_qtr <= 2007.4); 
	keep rssdid year_qtr year date0 date1 edo_mat edo disc log_dist TOT_ASSETS_LAG1 SIZE_LAG1 CAPITAL_RATIO_LAG1 NPA_LAG1 ROA_LAG1 ROA_QTR_LAG1 
	LIQ_CASH_LAG1 ch_CAPITAL_RATIO_LAG1 ch_LIQ_CASH_LAG1 CH_LOAN_LAG1 capital_ratio_disc npa_disc roa_disc ROA_QTR_DISC liq_cash_disc;
run; 

proc export data=mod.surv_data_8307 replace
	outfile="[redacted-path-cb8068b2a855]"
	dbms = csv;
delimiter=',';
run;

/************************************************************/
/* Include bank failure data sourced from the FDIC          */
/************************************************************/

/* Clean data, bank failure data downloaded from the Federal Deposit Insurance Corporation */

data fail1;
set fail.Bnk_failure;
	keep CERT FAIL CHARTER_CLASS EFFECTIVE_DATE INSTITUTION_NAME LOCATION;
	FAIL = 1;
	if Failure___Assistance = "FAILURE";
run;

/* Include additional identifiers and subset to commercial banks */

proc sql;
create table cert1 as select
	RSSD9001 as RSSDID,
	RSSD9999 as DATE,
	RSSD9048 as CHARTER_TYPE,
	RSSD9050 as FDIC_CERT
from bnk.master_commercial;
quit;

data cert2;
set cert1;
	drop DATE;
	if CHARTER_TYPE = 200;
	rename FDIC_CERT = CERT;
run;

proc sort data = cert2 nodupkey;
	by RSSDID CERT;
run;

proc sort data = fail1;
	by CERT;
run;

proc sort data = cert2;
	by CERT;
run;

data fail2;
merge fail1(IN=in1) cert2(IN=in2);
	by CERT;
	if in1 = 1 then output fail2;
run;

data fail3;
set fail2;
	if RSSDID = . then delete;
	YEAR = year(EFFECTIVE_DATE);
	IF (1983 <= YEAR <= 1997);
RUN;

/* merge the main dataset with bank variables and enforcement action data */ 

data call1; 
set mod.surv_data_complete; 
run; 

proc sort data = call1;
	by RSSDID;
run;

proc sort data = fail3;
	by RSSDID;
run;

data call2;
merge call1(IN=in1) fail3(IN=in2);
	by RSSDID;
	if in1 = 1 then output call2;
run;

/* Create FAIL_IND where last value = 1 */

data call3;
set call2;
by RSSDID;
	if (last.RSSDID and FAIL = 1) then FAIL_IND = 1;
	else FAIL_IND = 0;
run;

data mod.surv_data_fail;
set call3;
run;

proc export data=mod.surv_data_fail replace
	outfile="[redacted-path-511a0ff9d3a0]"
	dbms = csv;
delimiter=',';
run;

/******************************************************************************************************************/
/* Include news circulation data downloaded from the Inter-university Consortium for Political and Social Research. 
The data is the United States Newspaper Panel, 1869-2004 collected by Gentzkow, Shapiro, and Sinkinson (2011). 
/******************************************************************************************************************/

/* Include data on county fips */ 

proc sql;
create table cnty1 as select distinct
rssdid,
county_fips,
state_fips,
year 
from mod.bnk_vars_county
; 
quit; 

proc sort data = cnty1 nodupkey;
	by rssdid year;
run; 

data news1;
set mod.news_county_8397;
	county_fips = (substr(cnty90,length(cnty90)-2, 3))*1;
	state_fips = (substr(cnty90,1,length(cnty90)-3))*1;
run;

proc sql;
create table cnty2 as select*
from mod.surv_data_complete as a, cnty1 as b
where a.rssdid = b.rssdid and a.year = b.year;
quit;

proc sort data = cnty2;
	by state_fips county_fips year;
run;

proc sort data = news1;
	by state_fips county_fips year;
run;

data dat1;
merge cnty2(IN=in1) news1(IN=in2);
	by state_fips county_fips year;
	if in1 = 1 then output dat1;
run;

/* news circulation data is not available for all counties; 
* replace missing data with state average each year */

proc sort data = news1;
	by state_fips year;
run; 

proc means noprint data=news1;
	by state_fips year;
	VAR cov_pct;
	OUTPUT OUT=st_news(DROP=_TYPE_ _FREQ_)
	MEAN = cov_pct_state;
run;

proc sort data = dat1;
	by state_fips year;
run;

proc sort data = st_news;
	by state_fips year;
run;

data dat2;
merge dat1(IN=in1) st_news(IN=in2);
	by state_fips year;
	if in1 = 1 then output dat2;
run;

data dat3;
set dat2;
	if cov_pct = . then cov_pct = cov_pct_state;
run;

data mod.surv_data_news;
set dat3;
run;

proc export data=mod.surv_data_news replace
	outfile="[redacted-path-73388fc2e4b1]"
	dbms = csv;
delimiter=',';
run;

/* save */
data mod.bnk_vars; 
set var7_3; 
run;

/* lag to get beginning period values */

proc sort data = var1;
	by RSSDID DATE;
run;


proc expand data=var1 out=var2 method=none;
	by RSSDID;
	id DATE;
	convert TOT_ASSETS = TOT_ASSETS_LAG1 / transformout=(lag 1);
	convert EQUITY = EQUITY_LAG1 / transformout=(lag 1);
	convert TOT_DEPOSITS = TOT_DEPOSITS_LAG1 / transformout=(lag 1);
	convert TOTLOAN_NET = TOTLOAN_NET_LAG1 / transformout=(lag 1);
	convert NI = NI_LAG1 / transformout=(lag 1);
	convert NONINT_INC = NONINT_INC_LAG1 / transformout=(lag 1);
	convert INT_INC = INT_INC_LAG1 / transformout=(lag 1);
	convert INTINC_LOAN = INTINC_LOAN_LAG1 / transformout=(lag 1); 
	convert INT_DEP = INT_DEP_LAG1 / transformout= (lag 1);
run;

data var3;
set var2;
	AVG_ASSETS = (TOT_ASSETS + TOT_ASSETS_LAG1)/2; 
	AVG_EQUITY = (EQUITY + EQUITY_LAG1)/2;
	AVG_DEPOSITS = (TOT_DEPOSITS + TOT_DEPOSITS_LAG1)/2;
	AVG_LOAN_NET = (TOTLOAN_NET + TOTLOAN_NET_LAG1)/2;
	if QTR = 1 THEN do;
		NI_QTR = NI;
		INTINC_LOAN_QTR = INTINC_LOAN;
		INT_DEP_QTR = INT_DEP;
		INT_INC_QTR = INT_INC;
		NONINT_INC_QTR = NONINT_INC;
	end;
	ELSE IF QTR IN (2, 3, 4) THEN DO;
		NI_QTR = NI - NI_LAG1;
		INTINC_LOAN_QTR = INTINC_LOAN - INTINC_LOAN_LAG1;
		INT_DEP_QTR = INT_DEP - INT_DEP_LAG1;
		INT_INC_QTR = INT_INC - INT_INC_LAG1 ;
		NONINT_INC_QTR = NONINT_INC - NONINT_INC_LAG1;
	END;
run; 

data var4(DROP= RS_LOAN_SUB_CMRC_SUB: RS_LOAN_SUB_RESI_SUB:);
set var3;
	NET_CHRGOFF = (CHRGOFF - RECOV)/AVG_ASSETS;
	ROA = NI/AVG_ASSETS;
	ROA_QTR = NI_QTR/ AVG_ASSETS;
	NIM = NII/AVG_ASSETS;

	ROE = NI/EQUITY;
	NPA = (NONACC + PAST90)/TOTLOAN_NET;
	LIQ_CASH = CASH/TOT_ASSETS;
	LOAN_SC = TOTLOAN_NET/TOT_ASSETS; 
	DEPOSIT_SC = TOT_DEPOSITS/TOT_ASSETS; 
	INSURED_DEPOSIT = RCON2702/TOT_ASSETS;
	UNINSURED_DEPOSIT = (TOT_DEPOSITS-RCON2702)/TOT_ASSETS;
	SIZE = log(TOT_ASSETS);
	CAPITAL_RATIO = EQUITY/TOT_ASSETS;
	CI_LOAN = CI/TOTLOAN_NET;
	RE_LOAN = LOAN_RS/TOTLOAN_NET;
	OITA = OPER_INC/AVG_ASSET;
	IDTD = INT_DEP/AVG_DEPOSITS;

/* Clean data, calculate variables, subset to commercial banks */
data var1;
set RelVar; 
	YEAR = (substr(compress(DATE),1,4))*1; 
	QTR = ((substr(compress(DATE),5,2))*1)/3;
	YEAR_QTR = (cat(YEAR,".",QTR))*1; 
	TOTLOAN_NET = TOTLOAN_GROSS - ALLW_END - UNEARN_LOANINC;
	if CHARTER_TYPE = 200; 
run;
